window.I18N_FR_RX = [
  [/^in (\d+)h (\d+)m$/, "dans $1 h $2 min"],
  [/^in (\d+)m$/, "dans $1 min"],
  [/^~([\d,]+) steps$/, function (m, n) { return "~$1 pas".replace("$1", n.replace(/,/g, " ")); }],
  [/^Expand all (\d+) stops$/, "Déplier les $1 étapes"],
  [/^Right now · (.+) Eastern$/, "En ce moment · $1 heure de l’Est"],
  [/^Live forecast for all seven days, taken (.+?)\. Central Florida in October: warm, humid, and afternoon storms that pass\. Ponchos beat umbrellas in a queue\.$/, "Prévisions en direct pour les sept jours, relevées le $1. Le centre de la Floride en octobre : chaud, humide, avec des orages l’après-midi qui passent vite. Dans une file, le poncho vaut mieux que le parapluie."],
  [/^Live forecast for all seven days, taken (.+?) —$/, "Prévisions en direct pour les sept jours, relevées le $1 —"],
  [/^Live forecast for the first (\d+) days?, taken (.+?)\. The rest fill in automatically as the trip gets closer — forecasts only reach about 16 days ahead\.$/, "Prévisions en direct pour les $1 premier(s) jour(s), relevées le $2. Les autres se remplissent automatiquement à l’approche du voyage — les prévisions ne vont qu’à environ 16 jours."],
  [/^(.*?) ?Videos, live waits, weather and booking apps need internet\.$/, function (m, a) { return window.i18nT(a) + " Les vidéos, les temps d’attente en direct, la météo et les applis de réservation nécessitent internet."; }],
  [/^Offline itinerary ready on this device · checked (.+) Eastern\.( Some photos are unavailable offline\.| Local photos saved too\.)$/, function (m, w, x) { return "Itinéraire hors ligne prêt sur cet appareil · vérifié le " + w + " (heure de l’Est)." + (/Some/.test(x) ? " Certaines photos ne sont pas disponibles hors ligne." : " Les photos locales sont aussi enregistrées."); }],
  [/^Offline copy incomplete\. Reconnect and reload to retry \((\d+) required files unavailable\)\.$/, "Copie hors ligne incomplète. Reconnectez-vous et rechargez pour réessayer ($1 fichiers requis indisponibles)."],
  [/^Offline saving is unavailable in this browser\.$/, "L’enregistrement hors ligne n’est pas disponible dans ce navigateur."],
  [/^Checking the offline copy on this device…$/, "Vérification de la copie hors ligne sur cet appareil…"],
  [/^Offline copy not verified\. Reconnect or reload to retry; storage or downloads may be unavailable\.$/, "Copie hors ligne non vérifiée. Reconnectez-vous ou rechargez pour réessayer ; le stockage ou les téléchargements sont peut-être indisponibles."],
  [/^Offline saving failed\. Keep an online connection and retry after reloading\.$/, "Échec de l’enregistrement hors ligne. Restez connecté et réessayez après avoir rechargé."]
];
